package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type DateRec struct { // 01 DATE-REC, 12 bytes
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items
var WsEofFlag string = "N"
var WsLeapFlag string = "N"
var WsQ int64 = 0
var WsR4 int64 = 0
var WsR100 int64 = 0
var WsR400 int64 = 0
var WsMaxDay int64 = 0
var WsValid int64 = 0
var WsBadMonth int64 = 0
var WsBadDay int64 = 0

var DateRecVar DateRec

var dateFile *os.File
var dateScanner *bufio.Scanner

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func isLeap() bool {
	return WsLeapFlag == "Y"
}

func pow10(n int) int64 {
	m := int64(1)
	for i := 0; i < n; i++ {
		m *= 10
	}
	return m
}

func format9(v int64, width int) string {
	m := pow10(width)
	r := v % m
	if r < 0 {
		r += m
	}
	f := "%0" + strconv.Itoa(width) + "d"
	return fmt.Sprintf(f, r)
}

func parseNumField(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return 0
	}
	return n
}

func padTo(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func mainPara() {
	var err error
	dateFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}
	dateScanner = bufio.NewScanner(dateFile)
	// allow long lines just in case
	const maxCap = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	dateScanner.Buffer(buf, maxCap)
	readPara()
	for !isInputDone() {
		processPara()
	}
	if err := dateFile.Close(); err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}
	out := "VALID: " + format9(WsValid, 2) + " BAD MONTH: " + format9(WsBadMonth, 2) + " BAD DAY: " + format9(WsBadDay, 2)
	fmt.Fprintln(os.Stdout, out)
}

func readPara() {
	if dateScanner.Scan() {
		line := dateScanner.Text()
		rec := padTo(line, 12)
		DateRecVar.DtId = rec[0:4]
		DateRecVar.DtYyyy = parseNumField(rec[4:8])
		DateRecVar.DtMm = parseNumField(rec[8:10])
		DateRecVar.DtDd = parseNumField(rec[10:12])
	} else {
		if err := dateScanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err.Error())
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func processPara() {
	leapPara()
	if DateRecVar.DtMm < 1 || DateRecVar.DtMm > 12 {
		WsBadMonth = (WsBadMonth + 1) % 100
		out := DateRecVar.DtId + " BAD MONTH " + format9(DateRecVar.DtMm, 2)
		fmt.Fprintln(os.Stdout, out)
	} else {
		daysPara()
		if DateRecVar.DtDd < 1 || DateRecVar.DtDd > WsMaxDay {
			WsBadDay = (WsBadDay + 1) % 100
			out := DateRecVar.DtId + " BAD DAY " + format9(DateRecVar.DtDd, 2) + " MAX " + format9(WsMaxDay, 2)
			fmt.Fprintln(os.Stdout, out)
		} else {
			WsValid = (WsValid + 1) % 100
			out := DateRecVar.DtId + " VALID " + format9(DateRecVar.DtYyyy, 4) + "-" + format9(DateRecVar.DtMm, 2) + "-" + format9(DateRecVar.DtDd, 2)
			fmt.Fprintln(os.Stdout, out)
		}
	}
	readPara()
}

func leapPara() {
	// DIVIDE DT-YYYY BY 4 GIVING WS-Q REMAINDER WS-R4
	q := DateRecVar.DtYyyy / 4
	r := DateRecVar.DtYyyy % 4
	WsQ = q % pow10(4)
	WsR4 = r % pow10(3)
	// DIVIDE DT-YYYY BY 100
	q = DateRecVar.DtYyyy / 100
	r = DateRecVar.DtYyyy % 100
	WsQ = q % pow10(4)
	WsR100 = r % pow10(3)
	// DIVIDE DT-YYYY BY 400
	q = DateRecVar.DtYyyy / 400
	r = DateRecVar.DtYyyy % 400
	WsQ = q % pow10(4)
	WsR400 = r % pow10(3)
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func daysPara() {
	mm := DateRecVar.DtMm
	switch mm {
	case 2:
		if isLeap() {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
}

func main() {
	mainPara()
}
